void AdaptiveSession::assemble_trace_active_focus(HybridTraceEvent& trace) {
        trace.active_focus_family_count =
            run_.last_active_niche_stats.focus_family_count;
        trace.active_focus_member_count =
            run_.last_active_niche_stats.focus_member_count;
        trace.active_focus_target_quota =
            run_.last_active_niche_stats.focus_target_quota;
        trace.active_focus_family_cap =
            run_.last_active_niche_stats.focus_family_cap;
        trace.active_monitor_family_cap =
            run_.last_active_niche_stats.monitor_family_cap;
        trace.active_focus_ready_count =
            run_.last_active_focus_ready_count;
        trace.active_focus_cooldown_family_count =
            run_.last_active_focus_cooldown_family_count;
        trace.active_focus_stopped_family_count =
            run_.last_active_focus_stopped_family_count;
        trace.active_focus_stop_clear_count =
            run_.active_focus_stop_clear_count;
        trace.active_focus_remap_count =
            run_.epoch_active_focus_remap_count;
        trace.active_focus_reset_count =
            run_.epoch_active_focus_reset_count;
        trace.active_focus_selection_count =
            run_.epoch_active_focus_selection_count;
        this->prune_active_focus_rotation_history();
        trace.active_focus_rotation_history_count =
            static_cast<int>(run_.active_focus_rotation_history.size());
        trace.active_focus_rotation_blocked_count =
            run_.epoch_active_focus_rotation_blocked_count;
        trace.active_focus_rotation_fallback_count =
            run_.epoch_active_focus_rotation_fallback_count;
        trace.active_focus_soft_fill_candidate_count =
            run_.epoch_active_focus_soft_fill_candidate_count;
        trace.active_focus_soft_fill_move_count =
            run_.epoch_active_focus_soft_fill_move_count;
        trace.active_focus_soft_fill_anchor_count =
            run_.epoch_active_focus_soft_fill_anchor_count;
        trace.active_focus_stop_release_candidate_count =
            run_.epoch_active_focus_stop_release_candidate_count;
        trace.active_focus_stop_release_move_count =
            run_.epoch_active_focus_stop_release_move_count;
        trace.active_focus_last_rel_improvement =
            run_.last_active_focus_rel_improvement;
        trace.active_niche_best_merits = run_.last_active_niche_merit_snapshots;
        for (ActiveNicheMeritSnapshot& snapshot : trace.active_niche_best_merits) {
            snapshot.focus = this->active_focus_key_matches_current(snapshot.key);
            if (!snapshot.focus || !std::isfinite(snapshot.best_merit)) {
                continue;
            }
            if (!std::isfinite(trace.active_focus_best_merit) ||
                snapshot.best_merit < trace.active_focus_best_merit) {
                trace.active_focus_best_merit = snapshot.best_merit;
                trace.active_focus_best_key = snapshot.key;
                trace.active_focus_best_niche_index = snapshot.niche_index;
                trace.active_focus_best_population_index =
                    snapshot.best_population_index;
                trace.active_focus_best_member_count = snapshot.member_count;
            }
        }
}

